-- The tables merge_companies touches, column for column as on live Supabase (2026-10-25), with
-- their keys and the foreign keys to companies. For scripts/test-company-duplicates-migration.py only.
create extension if not exists "uuid-ossp";
do $$ begin create role anon; exception when duplicate_object then null; end $$;
do $$ begin create role authenticated; exception when duplicate_object then null; end $$;
create table account_events (id uuid not null default gen_random_uuid(), company_id uuid, event_date date not null, amount numeric(12,2) not null default 0, amount_inc_vat numeric(12,2), product_line text, order_id text, source text not null, created_at timestamp with time zone not null default now());
create table companies (id uuid not null default uuid_generate_v4(), name text not null, status text not null default 'prospect'::text, lead_source text, account_owner text, last_contact_date date, tags text[] default '{}'::text[], industry text, size text, address text, website text, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), deleted_at timestamp with time zone, last_human_touch date, next_touch_due date, standing_order_flag boolean not null default false, logo_url text, champion_contact_id uuid, decision_maker_contact_id uuid, blocker_contact_id uuid, blocker_label text, map_status text not null default 'unknown'::text, what_they_make text, acquisition_source text, acquisition_campaign text);
create table company_aliases (id uuid not null default gen_random_uuid(), company_id uuid not null, kind text not null, value text not null, source text, created_at timestamp with time zone not null default now());
create table contacts (id uuid not null default uuid_generate_v4(), name text not null, email text, phone text, line text, job_title text, company_id uuid, status text not null default 'uncontacted'::text, last_contacted_date date, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), phone_second text, deleted_at timestamp with time zone, identity_quality text not null default 'unknown'::text, outreach_language text not null default 'autodetect'::text, outreach_language_basis text not null default 'autodetect'::text);
create table customer_link (historical_customer_id text not null, crm_company_id uuid, match_confidence text not null default 'auto'::text, reviewed boolean not null default false, created_at timestamp with time zone default now());
create table deals (id uuid not null default uuid_generate_v4(), title text not null, stage text not null default 'research'::text, product text not null default 'Butter'::text, client text not null, company_id uuid, contact_ids uuid[] default '{}'::uuid[], value numeric, priority text default 'medium'::text, next_action text, followup_date date, last_outcome text, nudge_count integer default 0, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), workflow_action text not null default 'outreach'::text, nudge_stage text, sample_status text, deleted_at timestamp with time zone, draft_primary_ask text, currency text default 'THB'::text, close_date date, stage_probability numeric, lost_reason text, park_reason text, won_note text, decision_maker_contact_id uuid, buyer_reply text, stated_order_kg numeric, call_checklist jsonb);
create table enrichment_evidence (id uuid not null default gen_random_uuid(), entity_type text not null, entity_id uuid, company_id uuid not null, field text not null, value text not null, source_url text not null, source_tier text not null, quote text not null, quote_check text not null, outcome text not null, hold_reason text, method text, fetched_at timestamp with time zone not null, recorded_at timestamp with time zone not null default now(), run_ref text);
create table enrichment_proposals (id uuid not null default gen_random_uuid(), entity_type text not null, entity_id uuid, company_id uuid, field text not null, value text not null, current_value text, source_url text not null, source_tier text not null, quote text not null, quote_check text not null, reason text, status text not null default 'pending'::text, decision_note text, run_ref text, proposed_at timestamp with time zone not null default now(), telegram_message_id bigint, sent_at timestamp with time zone, decided_at timestamp with time zone, details jsonb, reject_reason text);
create table interactions (id uuid not null default uuid_generate_v4(), description text not null, channel text not null, direction text not null default 'unknown'::text, occurred_on date not null, occurred_at timestamp with time zone, company_id uuid, contact_ids uuid[] default '{}'::uuid[], deal_id uuid, product text, summary text, outcome text, followup_date date, approval_state text not null default 'not_applicable'::text, source text not null default 'manual_ui'::text, legacy_meeting_id uuid, deleted_at timestamp with time zone, created_at timestamp with time zone default now());
create table meetings (id uuid not null default uuid_generate_v4(), description text not null, type text not null, date date not null, company_id uuid, contact_ids uuid[] default '{}'::uuid[], deal_id uuid, product text, summary text, outcome text, followup_date date, created_at timestamp with time zone default now(), deleted_at timestamp with time zone, direction text not null default 'unknown'::text);
create table prospect_reviews (id uuid not null default gen_random_uuid(), company_id uuid not null, decision text not null, reason_code text not null, reason_note text, criterion_ref text, reviewed_at timestamp with time zone not null default now(), next_action text, next_action_owner text, next_action_due date, evidence_note text, evidence_links text[], needs_data_review boolean not null default false, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
alter table companies add primary key (id);
alter table contacts add primary key (id), add foreign key (company_id) references companies(id) on delete set null;
alter table deals add primary key (id), add foreign key (company_id) references companies(id) on delete set null;
alter table meetings add primary key (id), add foreign key (company_id) references companies(id) on delete set null;
alter table interactions add primary key (id), add foreign key (company_id) references companies(id) on delete set null;
alter table account_events add primary key (id), add foreign key (company_id) references companies(id) on delete cascade;
alter table enrichment_evidence add primary key (id), add foreign key (company_id) references companies(id) on delete cascade;
alter table enrichment_proposals add primary key (id), add foreign key (company_id) references companies(id) on delete cascade;
alter table company_aliases add primary key (id), add foreign key (company_id) references companies(id) on delete cascade;
create unique index company_aliases_once_idx on public.company_aliases (kind, lower(trim(value)));
alter table customer_link add primary key (historical_customer_id);
alter table prospect_reviews add primary key (id), add unique (company_id), add foreign key (company_id) references companies(id) on delete cascade;
grant usage on schema public to anon, authenticated;
grant select, insert, update, delete on all tables in schema public to anon, authenticated;
alter default privileges in schema public grant select, insert, update, delete on tables to anon, authenticated;
